# aos-agent - the unified agent interface: manage one agent on an aos-daemon (eca or loop/fsm agents alike); run by bin/aos-agent (generated by install.py), the body is this package.
from aos import flags as aos_flags
from aos.apps.agent import main

if __name__ == "__main__":
    aos_flags.run(main)   # stdout closed early by the other side (listen --follow | head -1) = quiet exit 141 (J5)
